export function isTableFullyVerified(table: PriceTable): boolean {
  return table.tiers.every((t) => t.verified);
}

/**
 * True when `usageMax` (from Klaviyo's Billing Usage API) is exactly one of the
 * table's tier boundaries. If not, our table does not describe this account.
 */
export function isKnownTierBoundary(usageMax: number, table: PriceTable): boolean {
  return table.tiers.some((t) => t.maxProfiles === usageMax);
}
